out=[[1]*18 for _ in range(18)]
# move left and right portions to upper corners
left={ (6,5),(6,7),(7,5),(7,6),(7,7),(8,5),(8,7),(9,5),(10,5)}
right={(6,10),(6,11),(7,9),(7,10),(7,11),(7,12),(8,11),(8,12),(9,9),(9,10),(9,11),(10,9),(10,10)}
axis={(6,8),(7,8)}
for r,c in left: out[r-6][c-5]=7
for r,c in right: out[r-6][c+5]=7
for r,c in axis: out[r][c]=7
for r in range(0,11):
    if out[r][8]!=7: out[r][8]=2
print('\n'.join(' '.join(map(str,row)) for row in out))
